from datetime import timedelta


def _is_workday(day, holidays):
    return day.weekday() < 5 and day not in holidays


def add_workdays(start, days, holidays=()):
    """Move by working days, rolling forward for a zero offset."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an integer")
    holidays = set(holidays or ())
    step = timedelta(days=-1 if days < 0 else 1)
    remaining = abs(days)
    current = start
    while remaining or not _is_workday(current, holidays):
        current += step
        if remaining and _is_workday(current, holidays):
            remaining -= 1
    return current


def count_workdays(first, last, holidays=()):
    """Count both endpoints, negating the count for a reversed range."""
    if first > last:
        return -count_workdays(last, first, holidays)
    holidays = set(holidays or ())
    return sum(
        _is_workday(first + timedelta(days=offset), holidays)
        for offset in range((last - first).days + 1)
    )
